/* eslint-disable max-len */
/**
 * **اللوجو نفسه، مش رسمة بتقلّده.**
 *
 * اللي كان هنا SVG مرسوم بالإيد بيحاكي العلامة: بيت وورقة بخطوط تقريبية، والاسم مكتوب
 * بخط النظام. النتيجة كانت شبه اللوجو من بعيد وغلط من قريب — الورقة مالهاش شكل ورقة
 * تكنو، والاسم بخط تاني، و«تكنو ثيرم & وايت» بالعربي مش موجودة أصلاً. وده كان بيتطبع
 * على كل فاتورة وسند بيخرج للعملاء.
 *
 * فبقى **الملف الأصلي** مخزّن هنا base64: خلفيته اتشالت فبيركب على أي لون، وحجمه اتظبط
 * (٤١ ك.ب) عشان ينفع يتحط في نافذة الطباعة اللي `window.open` بيفتحها — دي مالهاش عنوان
 * أساسي، فـ`src="/logo.png"` مابيتحملش فيها، والـdata URI بيتحمّل.
 *
 * و`mark` هو البيت والورقة لوحدهم، للأماكن الضيقة (القايمة المطوية، الأيقونة).
 */
import React from 'react';

export const BRAND = {
  green: '#3FA92B',
  orange: '#F07C1E',
  ink: '#111111',
  nameAr: 'تكنو ثيرم',
  nameEn: 'TechnoTherm',
  tagline: 'GERMAN TECHNOLOGY',
};

/** اللوجو الكامل — بيت + ورقة + الاسم بالإنجليزي والعربي. */
export const LOGO_DATA_URI = 'data:image/png;base64,';

/** البيت والورقة لوحدهم. */
export const MARK_DATA_URI = 'data:image/png;base64,';

/** نسبة العرض للارتفاع في كل نسخة — عشان الصورة ماتتمططش. */
const RATIO = { full: 520 / 480, mark: 1 };

/** اللوجو الكامل كـHTML خام — للترويسات المطبوعة. */
export function logoSvg(width = 220): string {
  return `<img src="${LOGO_DATA_URI}" width="${width}" `
    + `alt="${BRAND.nameEn} — ${BRAND.tagline}" style="display:block">`;
}

/** العلامة لوحدها كـHTML خام.
 *
 *  `color` مابقاش ليه معنى — دي صورة بألوانها. القديم كان بيرسمها بلون واحد، والنداء
 *  الوحيد اللي كان بيمرّره اتشال. الوسيط سايب عشان النداءات القديمة ماتقعش. */
export function markSvg(size = 48, _color?: string): string {
  return `<img src="${MARK_DATA_URI}" width="${size}" height="${size}" `
    + `alt="${BRAND.nameEn}" style="display:block">`;
}

export default function Logo({
  variant = 'full', width, style,
}: {
  variant?: 'full' | 'mark';
  /** العرض بالبكسل؛ الارتفاع بيتحسب من نسبة الصورة. */
  width?: number;
  /** مالوش تأثير — سايب عشان النداءات القديمة. */
  color?: string;
  style?: React.CSSProperties;
}) {
  const w = width ?? (variant === 'mark' ? 40 : 200);
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', ...style }}>
      <img
        src={variant === 'mark' ? MARK_DATA_URI : LOGO_DATA_URI}
        alt={`${BRAND.nameEn} — ${BRAND.tagline}`}
        width={w}
        height={Math.round(w / RATIO[variant])}
        style={{ objectFit: 'contain' }}
      />
    </span>
  );
}
